def parse_num(value: str, flag: str) -> int:
    try:
        if value.startswith("+"):
            return int(value[1:])
        n = int(value)
        if n < 0:
            raise ValueError
        return n
    except ValueError:
        die(f"error parsing flag {flag}: value is not a valid number: invalid digit found in string")


def parse_size(value: str, flag: str) -> int:
    m = re.fullmatch(r"([0-9]+)([KMG])?", value)
    if not m:
        die(f"error parsing flag {flag}: invalid size: invalid format for size '{value}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix")
    n = int(m.group(1))
    suffix = m.group(2)
    if suffix == "K":
        n *= 1024
    elif suffix == "M":
        n *= 1024 ** 2
    elif suffix == "G":
        n *= 1024 ** 3
    return n


def apply_unrestricted(opt: Options) -> None:
    if opt.unrestricted_count >= 1:
        opt.no_ignore = True
    if opt.unrestricted_count >= 2:
        opt.hidden = True
    if opt.unrestricted_count >= 3:
        opt.text = True


def set_color_spec(opt: Options, spec: str) -> None:
    parts = spec.split(":")
    if len(parts) >= 2:
        what = parts[0]
        if parts[1] == "none":
            if what == "match":
                opt.color_match = None
            elif what == "path":
                opt.color_path = None
            elif what == "line":
                opt.color_line = None
            return
    if len(parts) >= 3 and parts[1] == "fg":
        colors = {
            "black": 30, "red": 31, "green": 32, "yellow": 33,
            "blue": 34, "magenta": 35, "purple": 35, "cyan": 36,
            "white": 37,
        }
        code = colors.get(parts[2])
        if code is not None:
            seq = f"\x1b[0m\x1b[{code}m"
            if what == "match":
                # ripgrep's default keeps bold on matches when just the fg changes.
                opt.color_match = f"\x1b[0m\x1b[1m\x1b[{code}m"
            elif what == "path":
                opt.color_path = seq
            elif what == "line":
                opt.color_line = seq


