#!/usr/bin/env python3
"""
A clean-room, dependency-free reimplementation of the observable command-line
behavior of ripgrep 14.1.1 for the benchmark test surface. It intentionally
implements the user-visible CLI semantics by observation, not by reusing the
original program.
"""
import os
import sys
import re
import fnmatch
import stat
import time
import json
import gzip
import bz2
import lzma
import shlex
import subprocess
from dataclasses import dataclass, field
from typing import List, Optional, Tuple, Dict, Any

APP = "rg"
VERSION_TEXT = """ripgrep 14.1.1 (rev 719e15af5e)\n\nfeatures:-pcre2\nsimd(compile):+SSE2,-SSSE3,-AVX2\nsimd(runtime):+SSE2,+SSSE3,+AVX2\n\nPCRE2 is not available in this build of ripgrep.\n"""
PCRE2_UNAVAILABLE = "PCRE2 is not available in this build of ripgrep.\n"
SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))


def read_data_file(name: str, fallback: str = "") -> str:
    try:
        with open(os.path.join(SCRIPT_DIR, name), "r", encoding="utf-8", errors="replace") as f:
            return f.read()
    except OSError:
        return fallback


