def out_bytes(data: Any) -> None:
    if isinstance(data, bytes):
        sys.stdout.buffer.write(data)
    else:
        sys.stdout.buffer.write(str(data).encode("utf-8", "surrogateescape"))


def err(data: Any) -> None:
    if isinstance(data, bytes):
        sys.stderr.buffer.write(data)
    else:
        sys.stderr.buffer.write(str(data).encode("utf-8", "surrogateescape"))


def die(msg: str, code: int = 2) -> None:
    err(f"{APP}: {msg}\n")
    raise SystemExit(code)


