SHORT_TAKES_VALUE = set("efEgmjdMABCrtT")


def parse_num(value: str, flag: str) -> int:
    try:
        if value.startswith("+"):
            return int(value[1:])
        n = int(value)
        if n < 0:
            raise ValueError
        return n
    except ValueError:
        die(f"error parsing flag {flag}: value is not a valid number: invalid digit found in string")


def parse_size(value: str, flag: str) -> int:
    m = re.fullmatch(r"([0-9]+)([KMG])?", value)
    if not m:
        die(f"error parsing flag {flag}: invalid size: invalid format for size '{value}', which should be a non-empty sequence of digits followed by an optional 'K', 'M' or 'G' suffix")
    n = int(m.group(1))
    suffix = m.group(2)
    if suffix == "K":
        n *= 1024
    elif suffix == "M":
        n *= 1024 ** 2
    elif suffix == "G":
        n *= 1024 ** 3
    return n


def apply_unrestricted(opt: Options) -> None:
    if opt.unrestricted_count >= 1:
        opt.no_ignore = True
    if opt.unrestricted_count >= 2:
        opt.hidden = True
    if opt.unrestricted_count >= 3:
        opt.text = True


def set_color_spec(opt: Options, spec: str) -> None:
    parts = spec.split(":")
    if len(parts) >= 2:
        what = parts[0]
        if parts[1] == "none":
            if what == "match":
                opt.color_match = None
            elif what == "path":
                opt.color_path = None
            elif what == "line":
                opt.color_line = None
            return
    if len(parts) >= 3 and parts[1] == "fg":
        colors = {
            "black": 30, "red": 31, "green": 32, "yellow": 33,
            "blue": 34, "magenta": 35, "purple": 35, "cyan": 36,
            "white": 37,
        }
        code = colors.get(parts[2])
        if code is not None:
            seq = f"\x1b[0m\x1b[{code}m"
            if what == "match":
                # ripgrep's default keeps bold on matches when just the fg changes.
                opt.color_match = f"\x1b[0m\x1b[1m\x1b[{code}m"
            elif what == "path":
                opt.color_path = seq
            elif what == "line":
                opt.color_line = seq


def apply_flag(opt: Options, name: str, value: Optional[str], display_flag: str) -> None:
    # Special modes.
    if name == "help":
        opt.show_help = "long" if display_flag == "--help" else "short"
    elif name == "version":
        opt.show_version = True
    elif name == "pcre2-version":
        opt.pcre2_version = True
    elif name == "generate":
        opt.generate = value or ""
    elif name == "type-list":
        opt.type_list = True
    elif name == "files":
        opt.files = True
    elif name == "no-config":
        opt.no_config = True

    # Input/search.
    elif name == "regexp":
        opt.patterns.append(value or "")
        opt.used_pattern_flag = True
    elif name == "file":
        opt.pattern_files.append(value or "")
        opt.used_pattern_flag = True
    elif name == "pre":
        opt.pre = value if value else None
    elif name == "pre-glob":
        if value is not None:
            opt.pre_globs.append(make_glob_rule(value, False))
    elif name == "search-zip":
        opt.search_zip = True
    elif name == "case-sensitive":
        opt.case_mode = "sensitive"
    elif name == "ignore-case":
        opt.case_mode = "insensitive"
    elif name == "smart-case":
        opt.case_mode = "smart"
    elif name == "fixed-strings":
        opt.fixed = True
    elif name == "invert-match":
        opt.invert = True
    elif name == "line-regexp":
        opt.line_regexp = True
    elif name == "word-regexp":
        opt.word_regexp = True
    elif name == "max-count":
        opt.max_count = parse_num(value or "", display_flag)
    elif name == "stop-on-nonmatch":
        opt.stop_on_nonmatch = True
    elif name == "text":
        opt.text = True
    elif name == "binary":
        opt.binary = True
    elif name == "multiline":
        opt.multiline = True
    elif name == "multiline-dotall":
        opt.multiline_dotall = True
    elif name == "crlf":
        opt.crlf = True
    elif name == "null-data":
        opt.null_data = True
    elif name == "encoding":
        opt.encoding = value
    elif name == "pcre2":
        die("PCRE2 is not available in this build of ripgrep")
    elif name == "engine":
        if value in ("pcre2", "pcre2-auto-hybrid"):
            die("PCRE2 is not available in this build of ripgrep")
        if value not in ("default", "auto"):
            die(f"error parsing flag {display_flag}: choice '{value}' is unrecognized")
    elif name == "auto-hybrid-regex":
        pass
    elif name == "no-pcre2-unicode":
        pass
    elif name == "no-unicode":
        opt.no_unicode = True
    elif name in ("dfa-size-limit", "regex-size-limit", "threads"):
        # Accepted and ignored, but validate numbers for ordinary integer options.
        parse_num(value or "", display_flag)
    elif name in ("mmap", "no-mmap"):
        pass

    # Filters.
    elif name == "follow":
        opt.follow = True
    elif name == "hidden":
        opt.hidden = True
    elif name == "glob":
        opt.globs.append(make_glob_rule(value or "", opt.glob_case_insensitive))
    elif name == "iglob":
        opt.globs.append(make_glob_rule(value or "", True))
    elif name == "glob-case-insensitive":
        opt.glob_case_insensitive = True
    elif name == "ignore-file":
        opt.ignore_files.append(value or "")
    elif name == "ignore-file-case-insensitive":
        opt.ignore_file_case_insensitive = True
    elif name == "max-depth":
        opt.max_depth = parse_num(value or "", display_flag)
    elif name == "max-filesize":
        opt.max_filesize = parse_size(value or "", display_flag)
    elif name == "no-ignore":
        opt.no_ignore = True
    elif name == "no-ignore-dot":
        opt.no_ignore_dot = True
    elif name == "no-ignore-files":
        opt.no_ignore_files = True
    elif name == "no-ignore-vcs":
        opt.no_ignore_vcs = True
    elif name in ("no-ignore-exclude", "no-ignore-global", "no-ignore-parent"):
        # Global/parent git integration is outside the benchmark surface.
        pass
    elif name == "no-require-git":
        opt.no_require_git = True
    elif name == "one-file-system":
        opt.one_file_system = True
    elif name == "type":
        opt.type_include.append(value or "")
    elif name == "type-not":
        opt.type_exclude.append(value or "")
    elif name == "type-add":
        opt.type_adds.append(value or "")
    elif name == "type-clear":
        opt.type_clears.append(value or "")
    elif name == "unrestricted":
        opt.unrestricted_count += 1
        apply_unrestricted(opt)

    # Output.
    elif name == "after-context":
        opt.after = parse_num(value or "", display_flag)
        opt.context_active = True
    elif name == "before-context":
        opt.before = parse_num(value or "", display_flag)
        opt.context_active = True
    elif name == "context":
        n = parse_num(value or "", display_flag)
        opt.before = n
        opt.after = n
        opt.context_active = True
    elif name == "byte-offset":
        opt.byte_offset = True
    elif name == "column":
        opt.column = True
    elif name == "color":
        if value not in ("auto", "always", "ansi", "never"):
            die(f"error parsing flag {display_flag}: choice '{value}' is unrecognized")
        opt.color_mode = "always" if value == "ansi" else (value or "auto")
    elif name == "colors":
        set_color_spec(opt, value or "")
    elif name == "heading":
        opt.heading = True
    elif name == "no-heading":
        opt.heading = False
    elif name == "hostname-bin":
        pass
    elif name == "hyperlink-format":
        pass
    elif name == "include-zero":
        opt.include_zero = True
    elif name == "line-number":
        opt.line_number = True
    elif name == "no-line-number":
        opt.line_number = False
    elif name == "max-columns":
        n = parse_num(value or "", display_flag)
        opt.max_columns = None if n == 0 else n
    elif name == "max-columns-preview":
        opt.max_columns_preview = True
    elif name == "null":
        opt.null = True
    elif name == "only-matching":
        opt.only_matching = True
    elif name == "path-separator":
        opt.path_separator = value or ""
    elif name == "passthru":
        opt.passthru = True
    elif name == "pretty":
        opt.pretty = True
        opt.color_mode = "always"
