        opt.sort_reverse = False
    elif name == "sortr":
        if value not in ("none", "path", "modified", "accessed", "created"):
            die(f"error parsing flag {display_flag}: choice '{value}' is unrecognized")
        opt.sort = None if value == "none" else value
        opt.sort_reverse = True
    elif name == "sort-files":
        opt.sort = "path"
        opt.sort_reverse = False
    elif name == "trim":
        opt.trim = True
    elif name == "vimgrep":
        opt.vimgrep = True
        opt.with_filename = True
