        opt.with_filename = True
    elif name == "no-filename":
        opt.with_filename = False
    elif name == "context-separator":
        opt.context_separator = value or ""
    elif name == "field-context-separator":
        opt.field_context_separator = value or ""
    elif name == "field-match-separator":
        opt.field_match_separator = value or ""
    elif name in ("block-buffered", "line-buffered"):
        pass

    # Output modes.
    elif name == "count":
        opt.count = True
    elif name == "count-matches":
        opt.count_matches = True
    elif name == "files-with-matches":
        opt.files_with_matches = True
    elif name == "files-without-match":
